"use client";

import { ShieldCheck, Sparkles, UploadCloud } from "lucide-react";
import ThemeToggle from "./ThemeToggle";
import type { Snapshot } from "@/lib/types";

interface NavbarProps {
  snapshots: Snapshot[];
  selectedSnapshotId: number | null;
  onSelectSnapshot: (id: number | null) => void;
  hasData: boolean;
  onReset: () => void;
}

export default function Navbar({
  snapshots,
  selectedSnapshotId,
  onSelectSnapshot,
  hasData,
  onReset,
}: NavbarProps) {
  return (
    <header className="sticky top-0 z-50 backdrop-blur-md bg-white/80 dark:bg-[#090a0f]/80 border-b border-zinc-200/80 dark:border-white/[0.08] transition-colors">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-15">
          {/* Brand */}
          <div className="flex items-center gap-3">
            <button
              onClick={hasData ? onReset : undefined}
              className="flex items-center gap-2.5 text-left group cursor-pointer focus:outline-none"
            >
              <div className="w-8 h-8 rounded-lg bg-gradient-to-tr from-[#833ab4] via-[#fd1d1d] to-[#fcb045] flex items-center justify-center shadow-sm">
                <Sparkles className="w-4 h-4 text-white" />
              </div>
              <div className="flex items-baseline gap-2">
                <span className="font-bold text-base tracking-tight text-zinc-900 dark:text-white">
                  InstaPulse
                </span>
                <span className="hidden sm:inline-block text-[11px] font-medium px-2 py-0.5 rounded-full bg-zinc-100 dark:bg-zinc-800/80 text-zinc-600 dark:text-zinc-400 border border-zinc-200/60 dark:border-zinc-700/60">
                  Privacy-First
                </span>
              </div>
            </button>
          </div>

          {/* Center: Privacy Guarantee Pill */}
          <div className="hidden md:flex items-center gap-1.5 px-3 py-1 rounded-full bg-emerald-500/[0.06] border border-emerald-500/20 text-emerald-700 dark:text-emerald-400 text-xs font-medium">
            <ShieldCheck className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" />
            <span>100% In-Browser • Zero Server Calls</span>
          </div>

          {/* Right Controls */}
          <div className="flex items-center gap-2.5">
            {hasData && (
              <button
                onClick={onReset}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium text-zinc-600 dark:text-zinc-300 hover:bg-zinc-100 dark:hover:bg-zinc-800 border border-zinc-200 dark:border-zinc-700/80 transition-colors cursor-pointer"
                title="Upload another export or reset"
              >
                <UploadCloud className="w-3.5 h-3.5 text-zinc-500" />
                <span className="hidden sm:inline">New Upload</span>
              </button>
            )}

            {snapshots.length > 0 && (
              <select
                value={selectedSnapshotId ?? ""}
                onChange={(e) => {
                  const val = e.target.value;
                  onSelectSnapshot(val ? Number(val) : null);
                }}
                className="text-xs px-2.5 py-1.5 rounded-lg bg-zinc-100/90 dark:bg-zinc-800/90 border border-zinc-200 dark:border-zinc-700 text-zinc-800 dark:text-zinc-200 focus:outline-none focus:ring-1 focus:ring-purple-500 cursor-pointer max-w-[150px] sm:max-w-[200px] truncate"
              >
                <option value="">Current Session</option>
                {snapshots.map((s) => (
                  <option key={s.id} value={s.id}>
                    {s.label}
                  </option>
                ))}
              </select>
            )}

            <ThemeToggle />
          </div>
        </div>
      </div>
    </header>
  );
}
